import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return null;
        ByteArrayOutputStream sb = new ByteArrayOutputStream();
        while (c != -1 && c > ' ') { sb.write(c); c = read(); }
        return sb.toString(java.nio.charset.StandardCharsets.UTF_8);
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        int len = n, rounds = 0;
        StringBuilder sb = new StringBuilder();
        while (len > 1) {
            // Pair neighbors; the smaller rank wins, a leftover player advances.
            int m = 0;
            for (int i = 0; i < len; i += 2) a[m++] = i + 1 < len ? Math.min(a[i], a[i + 1]) : a[i];
            len = m;
            rounds++;
            sb.append(len);
            for (int i = 0; i < len; i++) sb.append(' ').append(a[i]);
            sb.append('\n');
        }
        System.out.print(rounds + "\n" + sb);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := rd.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return ""
	}
	b := []byte{}
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		b = append(b, c)
		c, err = rd.ReadByte()
	}
	return string(b)
}

func main() {
	n := readInt()
	a := make([]int, n)
	for i := range a {
		a[i] = readInt()
	}
	body := []byte{}
	rounds := 0
	for len(a) > 1 {
		// Pair neighbors; the smaller rank wins, a leftover player advances.
		m := 0
		for i := 0; i < len(a); i += 2 {
			if i+1 < len(a) {
				a[m] = min(a[i], a[i+1])
			} else {
				a[m] = a[i]
			}
			m++
		}
		a = a[:m]
		rounds++
		body = strconv.AppendInt(body, int64(m), 10)
		for _, x := range a {
			body = append(body, ' ')
			body = strconv.AppendInt(body, int64(x), 10)
		}
		body = append(body, '\n')
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteString(strconv.Itoa(rounds) + "\n")
	w.Write(body)
}
